import Ajv from "ajv";
import jsonPatch from "fast-json-patch";
import schema from "./🧬️schema/🔣️.json";

const subsets=["1️⃣cc1","2️⃣cc2","3️⃣cc3","4️⃣cc4","5️⃣cc5","6️⃣cc6"];
